// Authored, constrained fill-in exercises. Each blank targets one stated skill.
const c=(headers,body,definitions='')=>headers.split(',').filter(Boolean).map(h=>`#include <${h}>`).join('\n')+'\n'+definitions+'\nint main() { '+body+' }';
const r=(body,definitions='')=>definitions+'\nfn main() { '+body+' }';
const spellings={'typename T':['class T'],'class T':['typename T'],'const std::string&':['std::string const&'],'const auto&':['auto const&'],'enum class':['enum struct'],'noexcept':['noexcept(true)']};
const q=(subject,slug,concept,title,difficulty,prompt,code,answer,incorrect,explanation)=>({id:`${subject}/${slug}`,subject,concept,title,difficulty,minutes:[0,0.7,1.3,2.3,3.8][difficulty],prompt,code:`// ${concept}.\n${code}`,answer,...(spellings[answer]?{alternatives:spellings[answer]}:{}),incorrect,explanation});
function ordered(rows){const previous={};return rows.map(row=>{const prerequisites=previous[row.subject]?[previous[row.subject]]:[];previous[row.subject]=row.id;return {...row,prerequisites};});}
